using System.Text;
using MySqlConnector;

namespace NextStep.Api;

// Server-side opt-in for external extraction of ONE imported evidence
// source (combined integration requirement). Deliberately separate from
// DisclosureStore: the plan-generation acknowledgment covers plan context
// leaving for generation; this opt-in covers a specific document's text
// leaving for extraction. Neither record implies the other, they live in
// different tables, and each is checked at its own boundary. OptedInAt is
// generated by the server; the client never supplies it.
public sealed class EvidenceOptInStore(MySqlStateStore store)
{
    public async Task<EvidenceImportOptIn?> Get(string owner, string sourceId, CancellationToken ct)
    {
        await using var connection = await store.Open(ct);
        await using var command = new MySqlCommand("SELECT version, opted_in_at, source_hash FROM evidence_import_optins WHERE owner_id=@owner AND source_id=@source", connection);
        command.Parameters.AddWithValue("@owner", owner);
        command.Parameters.AddWithValue("@source", sourceId);
        await using var reader = await command.ExecuteReaderAsync(ct);
        return await reader.ReadAsync(ct) ? new EvidenceImportOptIn(reader.GetInt32(0), reader.GetString(1), reader.GetString(2)) : null;
    }

    public async Task Set(string owner, string sourceId, EvidenceImportOptIn optIn, CancellationToken ct)
    {
        await using var connection = await store.Open(ct);
        await using var command = new MySqlCommand("INSERT INTO evidence_import_optins(owner_id, source_id, version, opted_in_at, source_hash) VALUES(@owner, @source, @version, @at, @hash) ON DUPLICATE KEY UPDATE version=VALUES(version), opted_in_at=VALUES(opted_in_at), source_hash=VALUES(source_hash)", connection);
        command.Parameters.AddWithValue("@owner", owner);
        command.Parameters.AddWithValue("@source", sourceId);
        command.Parameters.AddWithValue("@version", optIn.Version);
        command.Parameters.AddWithValue("@at", optIn.OptedInAt);
        command.Parameters.AddWithValue("@hash", optIn.SourceHash);
        await command.ExecuteNonQueryAsync(ct);
    }

    public async Task Clear(string owner, string sourceId, CancellationToken ct)
    {
        await using var connection = await store.Open(ct);
        await using var command = new MySqlCommand("DELETE FROM evidence_import_optins WHERE owner_id=@owner AND source_id=@source", connection);
        command.Parameters.AddWithValue("@owner", owner);
        command.Parameters.AddWithValue("@source", sourceId);
        await command.ExecuteNonQueryAsync(ct);
    }
}

// The versioned opt-in policy for evidence extraction. Bumping
// CurrentVersion when the extraction disclosure text materially changes
// makes earlier opt-ins stop counting until the student opts in again.
// An opt-in also stops counting when the document's content fingerprint
// no longer matches the fingerprint recorded at opt-in time, so replacing
// or materially updating a source always requires a renewed opt-in.
public static class EvidenceOptIn
{
    public const int CurrentVersion = 1;

    public static string Fingerprint(ProfessionalSource source)
    {
        var text = new StringBuilder();
        text.Append(source.Kind).Append('\n').Append(source.Title).Append('\n').Append(source.Revision ?? "");
        foreach (var chunk in source.Chunks) text.Append('\n').Append(chunk.Id).Append('\n').Append(chunk.Text);
        return MySqlStateStore.Hash(text.ToString());
    }

    public static bool Current(EvidenceImportOptIn? optIn, ProfessionalSource source) =>
        optIn is not null && optIn.Version == CurrentVersion && optIn.SourceHash == Fingerprint(source);

    public static EvidenceImportOptInStatus Status(EvidenceImportOptIn? optIn, ProfessionalSource source) => new(
        CurrentVersion,
        Current(optIn, source),
        optIn?.OptedInAt,
        optIn?.Version);

    public static void RequireCurrent(EvidenceImportOptIn? optIn, ProfessionalSource source)
    {
        if (!Current(optIn, source))
            throw new ApiFault("evidence_optin_required", $"Confirm the extraction opt-in for \"{source.Title}\" before its text is sent for analysis. Nothing was sent.");
    }
}
